    def target = rootProject.findProject(':opentaint-dataflow')
    target.extensions.getByName('kotlin').sourceSets.getByName('test').kotlin.srcDir(
        '/drive-testcomp/opentaint-go-rules/constant-filter-target-zero-20261031/analysis-tools/backward-design-controls/src')
